-- public.creature_level(p_skills jsonb, p_species text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.creature_level(p_skills jsonb, p_species text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select greatest(1, floor(coalesce(case when ls.skill is null then (select max(value::numeric) from jsonb_each_text(p_skills))
                                         else (p_skills->>ls.skill)::numeric end, 0)))::int
    from (select level_skill(p_species) as skill offset 0) ls
  );
end $function$
